<script setup lang="ts">import { onMounted,ref } from 'vue';import { useRoute } from 'vue-router';import { api } from '../../api';import DataStatusTag from '../../components/common/DataStatusTag.vue';import SourceCard from '../../components/common/SourceCard.vue';const route=useRoute();const items=ref<any[]>([]);const detail=ref<any>(null);onMounted(async()=>{if(route.params.id)detail.value=await api.pathwayDetail(String(route.params.id));else items.value=await api.pathways()})</script><template><section class="content-page"><div class="eyebrow">PATHWAYS / DIRECTORY</div><template v-if="detail"><h1>{{detail.name}}</h1><p class="lede">{{detail.description}}</p><DataStatusTag :status="detail.data_status"/><div class="feature-card" v-for="c in detail.conditions" :key="c.text"><h3>{{c.text}}</h3><SourceCard :citation="{source_name:c.source_name,source_url:c.source_url,year:2026}"/></div></template><template v-else><h1>升学途径</h1><p class="lede">先了解路径，再判断自己是否适合。</p><div class="result-grid"><RouterLink v-for="p in items" :key="p.pathway_id" class="feature-card" :to="`/pathways/${p.pathway_id}`"><span class="card-index">{{p.category}} · {{p.priority}}</span><h2>{{p.name}}</h2><p>{{p.target_group}}</p><DataStatusTag :status="p.data_status"/></RouterLink></div></template></section></template>
